/**
 * Writes src/environments/build-info.ts just before the bundle is built.
 *
 * Why this exists: a deployed frontend was indistinguishable from a stale cached one. Working out
 * whether a fix was actually live meant downloading the bundle and grepping it for a symbol — which
 * is slow, needs someone who knows what symbol to look for, and gets the answer wrong when the code
 * lives in a lazy chunk rather than main.js. A visible stamp answers it in a glance.
 *
 * Generated rather than committed, so it cannot drift from the commit it claims to describe. The
 * generated file is gitignored for the same reason.
 */
import { execSync } from 'node:child_process';
import { mkdirSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const target = join(here, '..', 'src', 'environments', 'build-info.ts');

/**
 * The commit, however this build can discover it.
 *
 * Vercel checks out a detached HEAD and does not always leave a usable git dir, so its own
 * environment variable is tried first. `git` is the local-development answer. Neither is fatal:
 * a build with an unknown commit is still worth stamping with a time.
 */
function commit() {
  const fromCi = process.env.VERCEL_GIT_COMMIT_SHA || process.env.GITHUB_SHA;
  if (fromCi) return fromCi.slice(0, 7);
  try {
    return execSync('git rev-parse --short HEAD', { stdio: ['ignore', 'pipe', 'ignore'] })
      .toString()
      .trim();
  } catch {
    return 'unknown';
  }
}

// ISO-8601 in UTC. Rendered in the viewer's own zone by the footer — the stamp itself stays
// unambiguous so two people in different offices can compare what they are looking at.
const builtAt = new Date().toISOString();
const sha = commit();

const contents = `// GENERATED by scripts/write-build-info.mjs at build time. Do not edit, do not commit.
export const BUILD_INFO = {
  commit: '${sha}',
  builtAt: '${builtAt}',
} as const;
`;

mkdirSync(dirname(target), { recursive: true });
writeFileSync(target, contents, 'utf8');
console.log(`build-info: ${sha} @ ${builtAt}`);
